            if e.code == 429:
                wait = e.headers.get('Retry-After')
                if wait is None:
                    try: wait = json.loads(body).get('wait_seconds')
                    except Exception: pass
                time.sleep(float(wait or 1)); continue
            if e.code >= 500:
                time.sleep(1); continue
            raise RuntimeError(f'token HTTP {e.code}: {body}')
        except (urllib.error.URLError, TimeoutError) as e:
