        req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.loads(resp.read())
        except urllib.error.HTTPError as e:
            body = e.read().decode('utf-8', 'replace')
            if e.code == 401:
                token = None
                continue
            if e.code == 429:
                wait = e.headers.get('Retry-After')
                if wait is None:
                    try:
                        payload = json.loads(body)
                        wait = payload.get('wait_seconds', payload.get('retry_after'))
                    except Exception: pass
                time.sleep(float(wait or 1)); continue
            if e.code >= 500:
                time.sleep(1); continue
            raise RuntimeError(f'{path} HTTP {e.code}: {body}')
        except (urllib.error.URLError, TimeoutError):
            time.sleep(1)

# Follow documented pagination links and count each repeated appearance after the first.
orders_by_id = {}
listing_count = 0
path = '/orders?page=1'
total_pages = None
while path:
    page = request_json(path)
    if total_pages is None:
        total_pages = page['total_pages']
    for order in page['items']:
        listing_count += 1
        oid = str(order['id'])
        if oid not in orders_by_id:
            orders_by_id[oid] = order
    path = page.get('next')

# Date boundaries are explicit UTC instants and timestamps retain their supplied offsets.
start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
qualifying = []
for order in orders_by_id.values():
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if start <= placed < end:
        qualifying.append(order)

customers = {}
for order in qualifying:
    cid = str(order['customer_id'])
    if cid not in customers:
        customers[cid] = request_json('/customers/' + urllib.request.pathname2url(cid))

regions = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    customer = customers[str(order['customer_id'])]
    numerator = int(order['amount_cents']) * (100 - int(customer['discount_pct']))
    discounted = (numerator + 50) // 100
    regions[customer['region']] += discounted
result = {
    'total_cents': sum(regions.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': listing_count - len(orders_by_id),
    'by_region': regions,
}
print(json.dumps({'result': result, 'pages': total_pages, 'unique_listed_orders': len(orders_by_id), 'listing_count': listing_count, 'customers_cached': len(customers)}, indent=2))
